SELECT setval(pg_get_serial_sequence('penonton', 'id_penonton'), coalesce(max(id_penonton), 1)) FROM penonton;
SELECT setval(pg_get_serial_sequence('item_merch', 'id_item'), coalesce(max(id_item), 1)) FROM item_merch;
SELECT setval(pg_get_serial_sequence('kupon', 'id_kupon'), coalesce(max(id_kupon), 1)) FROM kupon;
SELECT setval(pg_get_serial_sequence('artis', 'id_artis'), coalesce(max(id_artis), 1)) FROM artis;
SELECT setval(pg_get_serial_sequence('vendor', 'id_vendor'), coalesce(max(id_vendor), 1)) FROM vendor;
SELECT setval(pg_get_serial_sequence('sponsor', 'id_sponsor'), coalesce(max(id_sponsor), 1)) FROM sponsor;
SELECT setval(pg_get_serial_sequence('panitia', 'id_panitia'), coalesce(max(id_panitia), 1)) FROM panitia;
SELECT setval(pg_get_serial_sequence('lokasi_pertunjukan', 'id_lokasi'), coalesce(max(id_lokasi), 1)) FROM lokasi_pertunjukan;
SELECT setval(pg_get_serial_sequence('jadwal_pertunjukan', 'id_jadwal_pertunjukan'), coalesce(max(id_jadwal_pertunjukan), 1)) FROM jadwal_pertunjukan;
